begin;
create table if not exists hq.technology_systems(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),name text not null,system_type text not null,environment text not null check(environment in('production','staging','development','external')),status text not null default 'operational' check(status in('operational','degraded','maintenance','outage','retired')),base_url text,owner_employee_id uuid not null references hq.employees(id),last_checked_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(legal_entity_id,name,environment));
create table if not exists hq.technology_integrations(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),name text not null,provider text not null,integration_type text not null,status text not null default 'pending' check(status in('pending','active','degraded','disabled')),secret_reference text,health_endpoint text,last_success_at timestamptz,last_failure_at timestamptz,owner_employee_id uuid not null references hq.employees(id),created_at timestamptz not null default now(),check(secret_reference is null or secret_reference not like '%BEGIN%'));
create table if not exists hq.technology_incidents(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),system_id uuid references hq.technology_systems(id),title text not null,severity text not null check(severity in('sev4','sev3','sev2','sev1')),status text not null default 'open' check(status in('open','investigating','mitigated','resolved','closed')),description text,started_at timestamptz not null,resolved_at timestamptz,root_cause text,resolution text,owner_employee_id uuid not null references hq.employees(id),created_at timestamptz not null default now());
create table if not exists hq.technology_backups(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),system_id uuid references hq.technology_systems(id),backup_type text not null,storage_reference text not null,started_at timestamptz not null,completed_at timestamptz,status text not null check(status in('running','succeeded','failed','expired')),size_bytes bigint,restore_tested_at timestamptz,retention_until date,created_at timestamptz not null default now());
create table if not exists hq.technology_changes(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),system_id uuid references hq.technology_systems(id),title text not null,change_type text not null,risk_level text not null check(risk_level in('low','medium','high','critical')),status text not null default 'planned' check(status in('planned','approved','in_progress','completed','rolled_back','cancelled')),scheduled_at timestamptz,completed_at timestamptz,rollback_plan text,requested_by uuid not null references hq.employees(id),approved_by uuid references hq.employees(id),created_at timestamptz not null default now(),check(requested_by is null or approved_by is null or requested_by<>approved_by));
do $$ declare t text;begin foreach t in array array['technology_systems','technology_integrations','technology_incidents','technology_backups','technology_changes'] loop execute format('alter table hq.%I enable row level security',t);execute format('revoke all on hq.%I from public,anon,authenticated',t);execute format('grant all on hq.%I to service_role',t);end loop;end $$;
create index if not exists idx_hq_tech_incidents on hq.technology_incidents(status,severity,started_at desc);create index if not exists idx_hq_tech_backups on hq.technology_backups(status,started_at desc);create index if not exists idx_hq_tech_changes on hq.technology_changes(status,scheduled_at);
commit;
